@page "/chat"
@using sv_68f63ec084324025a635755aba7d94c6.Services
@namespace sv_68f63ec084324025a635755aba7d94c6.Components.Pages.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="sidebar-panel">
        <ChannelSidebar Channels="channels"
                        ActiveChannelId="selectedChannel?.Id ?? 0"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-panel @(isThreadOpen ? "" : "expanded")">
        @if (selectedChannel is not null)
        {
            <div class="main-header">
                <h2># @selectedChannel.Name</h2>
                <p>@selectedChannel.Description</p>
            </div>

            <MessageList Messages="messages"
                         ThreadReplyCounts="threadReplyCounts"
                         IsLoadingMore="isLoadingMore"
                         OnLoadMore="LoadOlderMessages"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction" />

            <MessageInput OnSend="SendMessage" />
        }
        else
        {
            <div class="empty-state">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (isThreadOpen)
    {
        <div class="thread-panel-container">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnReplySend="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private Dictionary<int, int> threadReplyCounts = [];
    private bool isLoadingMore;
    private const int PageSize = 30;

    // Thread state
    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannel = channel;
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channel.Id);
        ComputeThreadCounts();
        CloseThreadSync();
    }

    private async Task LoadOlderMessages()
    {
        if (isLoadingMore || selectedChannel is null) return;

        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(selectedChannel.Id, messages.Count, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            ComputeThreadCounts();
        }
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var newMessage = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(newMessage);
    }

    private async Task OpenThread(Message rootMessage)
    {
        threadRootMessage = rootMessage;
        threadReplies = await ChatService.GetThreadAsync(rootMessage.Id);
        isThreadOpen = true;
    }

    private async Task CloseThread()
    {
        CloseThreadSync();
        await Task.CompletedTask;
    }

    private void CloseThreadSync()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null || selectedChannel is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update the reply count
        if (threadReplyCounts.ContainsKey(threadRootMessage.Id))
            threadReplyCounts[threadRootMessage.Id]++;
        else
            threadReplyCounts[threadRootMessage.Id] = 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        // Refresh the affected message's reactions
        if (selectedChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(selectedChannel.Id, 0, messages.Count);
        }
    }

    private void ComputeThreadCounts()
    {
        threadReplyCounts = messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.sidebar-panel {
    width: 20%;
    min-width: 200px;
    flex-shrink: 0;
}

.main-panel {
    width: 55%;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    transition: width 0.2s ease;
}

.main-panel.expanded {
    width: 80%;
}

.thread-panel-container {
    width: 25%;
    min-width: 280px;
    flex-shrink: 0;
}

.main-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e5e7eb;
    background: #ffffff;
}

.main-header h2 {
    margin: 0;
    font-size: 1.15rem;
    color: #1a1a2e;
}

.main-header p {
    margin: 2px 0 0;
    font-size: 0.8rem;
    color: #6b7280;
}

.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #9ca3af;
    font-size: 1rem;
}

