toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.sidebar-panel {
    width: 20%;
    min-width: 200px;
    flex-shrink: 0;
}

.main-panel {
    width: 55%;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    transition: width 0.2s ease;
}

.main-panel.expanded {
    width: 80%;
}

.thread-panel-container {
    width: 25%;
    min-width: 280px;
    flex-shrink: 0;
}

.main-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e5e7eb;
    background: #ffffff;
}

.main-header h2 {
    margin: 0;
    font-size: 1.15rem;
    color: #1a1a2e;
}

.main-header p {
    margin: 2px 0 0;
    font-size: 0.8rem;
    color: #6b7280;
}

.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #9ca3af;
    font-size: 1rem;
}

